    },
    {
      "id": "2-1",
      "type": "iteration-start",
      "param": {}
    },
    {
      "id": "2-2",
      "type": "document-extractor",
      "param": {
        "variable_selector": ["item", "2"]
      }
    },
    {
      "id": "2-3",
      "type": "llm",
      "param": {
        "system": "You are an expert in document analysis. First, comprehensively parse the structure of the article whose text is provided. Identify sections, subsections, headings, and logical parts.",
        "user": "Here is the full text of a document:\n\n{{#\"2-2\".text#}}\n\n1) Parse the overall structure of the article.\n2) List the main parts/sections and their roles in the article.\n\nReturn your result in a clear, structured way."
      }
    },
    {
      "id": "2-4",
      "type": "llm",
      "param": {
        "system": "You are an expert in content analysis and summarization.",
        "user": "You have the following structural analysis of a document:\n\n{{#\"2-3\".text#}}\n\nTask:\n1) For each part/section identified above, briefly explain its main content and its function in the overall article.\n2) Based on this parsing and analysis, write a concise but comprehensive summary of the entire article.\n\nOutput format:\n- Section analysis: bullet list\n- Final summary: 1-3 paragraphs of continuous text.\n\nOnly output the final answer, no extra explanations."
      }
    },
    {
      "id": "3",
      "type": "template-transform",
      "param": {
        "variables": [
          ["doc_summaries", ["output", "2"]]
        ],
        "template": "{% for s in doc_summaries %}## Document {{ loop.index }} Summary\n\n{{ s }}\n\n{% endfor %}"
      }
    },
    {
      "id": "4",
      "type": "markdown-exporter",
      "param": {
        "target_type": "docx",
        "md_text": "{{#\"3\".output#}}"
      }
    },
    {
      "id": "5",
      "type": "end",
      "param": {
        "outputs": [
          ["summary", ["output", "3"]],
          ["docx_file", ["files", "4"]]
        ]
      }
    }
  ],
  "edges": [
