{
  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["book", "string"],
          ["author", "string"]
        ]
      }
    },
    {
      "id": "2",
      "type": "llm",
      "param": {
        "system": "You are an expert book summarizer who creates engaging, accurate, and concise speed-read versions of books.\n\nYour job is to produce a \"three-minute speed-read\" script for the given book.\n\nGeneral requirements:\n- Aim for a length that can be read aloud in about 3 minutes by an average speaker (roughly 400–600 words).\n- Write in clear, natural, narrative prose, not bullet points.\n- Make it engaging but efficient: no filler, no long digressions.\n- Preserve the main plot arc, key characters, and core ideas or themes.\n- Avoid unnecessary minor details, subplots, or long descriptions.\n- If the book is non-fiction, focus on the core arguments, key concepts, and most important examples.\n- If the book is obscure or ambiguous from the title, make reasonable assumptions and produce a coherent, self-contained summary.\n- Do not add meta-commentary (e.g., \"this is a summary\" or \"in this speed-read\"); just give the content itself.\n- The output should be ready to be read aloud as-is.",
        "user": "Book title: {{#\"1\".book#}}\nAuthor: {{#\"1\".author#}}\n\nTask: Based on the title and author, create a three-minute speed-read version of this book.\n\nInstructions:\n1. Start with 1–2 sentences that set up the premise or central idea.\n2. Then walk through the main storyline or argument in a logical order.\n3. Introduce only the most important characters or concepts by name.\n4. Highlight the key turning points, conflicts, or insights.\n5. End with a brief closing that captures the resolution or main takeaway.\n\nWrite in continuous prose suitable for being read aloud in about three minutes."
      }
    },
    {
      "id": "3",
      "type": "end",
      "param": {
        "outputs": [
          ["result", ["text", "2"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2", 0, "3"]
  ]
}

