        "code": "import io
import json

import pandas as pd


def main(excel_file):
	"""
	excel_file: Dify file object with at least `bytes` attribute (binary content) or `path`.
	Return JSON string with all sheets.
	"""
	# Try reading from bytes first; fall back to path if needed.
	data = None
	# Some environments provide `excel_file["bytes"]`, others `excel_file["path"]`.
	if isinstance(excel_file, dict):
		content = excel_file.get("bytes")
		path = excel_file.get("path")
	else:
		# If the object is not a dict, just try to use it as bytes-like
		content = getattr(excel_file, "bytes", None)
		path = getattr(excel_file, "path", None)

	try:
		if content is not None:
			buffer = io.BytesIO(content)
			data = pd.read_excel(buffer, sheet_name=None)
		elif path is not None:
			data = pd.read_excel(path, sheet_name=None)
		else:
			raise ValueError("excel_file has neither bytes nor path.")
	except Exception as e:
		# In case of error, return a JSON with error message
		return {
			"json_result": json.dumps({"error": str(e)})
		}

	# Convert each sheet DataFrame to list-of-dicts
	result = {}
	for sheet_name, df in data.items():
		# Replace NaN with None for JSON compatibility
		clean_df = df.where(pd.notnull(df), None)
		result[str(sheet_name)] = clean_df.to_dict(orient="records")

	json_str = json.dumps(result, ensure_ascii=False)
	return {
		"json_result": json_str
	}"
      }
