      "id": "6",
      "type": "code",
      "param": {
        "variables": [
          ["html", ["body", "5"]]
        ],
        "outputs": [
          ["chunks", "array[string]"]
        ],
        "code": "def main(html: str):\n\timport re\n\t# very rough HTML tag removal\n\ttext = re.sub(r'<[^>]+>', ' ', html or '')\n\ttext = re.sub(r'\\s+', ' ', text).strip()\n\tchunk_size = 1500\n\tchunks = []\n\tfor i in range(0, len(text), chunk_size):\n\t\tchunk = text[i:i+chunk_size].strip()\n\t\tif chunk:\n\t\t\tchunks.append(chunk)\n\treturn {\"chunks\": chunks}"
      }
    },

    /* Iteration over chunks */
    {
      "id": "7",
      "type": "iteration",
      "param": {
        "iterator_selector": ["chunks", "6"],
        "output_selector": ["text", "7-2"]
      }
    },
    {
      "id": "7-1",
      "type": "iteration-start",
      "param": {}
    },
    {
      "id": "7-2",
      "type": "llm",
      "param": {
        "system": "You are an expert technical writer. Your job is to summarize knowledge from a single chunk of a web page.",
        "user": "Here is one chunk of the web page content:\n\n{{#\"7\".item#}}\n\nSummarize the key knowledge points from this chunk in a concise paragraph. Do NOT reference other chunks, only this one."
      }
    },

    /* Global summarizer + mind-map generator */
    {
      "id": "8-1",
      "type": "llm",
      "param": {
        "system": "You are an expert knowledge distiller and mind map designer using Mermaid.",
        "user": "You will receive multiple partial summaries of a web page. Each element in the list is the summary of one chunk.\n\nChunk summaries:\n{{#\"7\".output#}}\n\nTasks:\n1. Synthesize these chunk-level summaries into ONE coherent, well-structured overall knowledge summary of the page.\n2. Design a **Mermaid mind map** that represents the main topic and its subtopics and key points.\n\nOutput format (strict):\n[SUMMARY]\n<write the final knowledge summary here as plain text>\n\n[MERMAID]\n<write ONLY valid Mermaid mindmap code here, no backticks, no extra text>\n\nExample structure for the Mermaid part (do NOT reuse content, just the structure):\n\nmindmap\n  root((Main Topic))\n    Subtopic 1\n      Detail A\n      Detail B\n    Subtopic 2\n      Detail C\n\nRemember: the [MERMAID] section must contain only Mermaid mindmap syntax."
      }
    },

    /* Extract summary and mermaid code from 8-1.text */
    {
      "id": "8",
      "type": "code",
      "param": {
        "variables": [
          ["combined", ["text", "8-1"]]
        ],
        "outputs": [
          ["summary", "string"],
          ["mermaid_code", "string"]
        ],
        "code": "def main(combined: str):\n\ttext = combined or ''\n\tsummary = ''\n\tmermaid = ''\n\tif '[SUMMARY]' in text and '[MERMAID]' in text:\n\t\tparts = text.split('[SUMMARY]', 1)[1]\n\t\tsummary_part, mermaid_part = parts.split('[MERMAID]', 1)\n\t\tsummary = summary_part.strip()\n\t\tmermaid = mermaid_part.strip()\n\telse:\n\t\t# fallback: try to guess last mindmap block\n\t\tsummary = text.strip()\n\t\tmermaid = ''\n\treturn {\"summary\": summary, \"mermaid_code\": mermaid}"
      }
    },
    {
      "id": "9",
      "type": "mermaid-converter",
      "param": {
        "mermaid_code": "{{#\"8\".mermaid_code#}}"
      }
    },

    /* Dummy summary for architecture branch to unify type */
    {
      "id": "10",
      "type": "code",
      "param": {
        "variables": [],
        "outputs": [
          ["summary", "string"]
        ],
        "code": "def main():\n\t# Empty summary used when only the architecture branch is used\n\treturn {\"summary\": \"\"}"
      }
    },

    /* Aggregators */
    {
      "id": "11",
      "type": "variable-aggregator",
      "param": {
        "variables": [
          ["text", "2"],
