      "param": {
        "variables": [
          ["summary", "10"],
          ["summary", "8"]
        ]
      }
    },

    {
      "id": "4",
      "type": "end",
      "param": {
        "outputs": [
          ["mermaid_code", ["output", "11"]],
          ["mermaid_pic", ["output", "12"]],
          ["summary", ["output", "13"]]
        ]
      }
    }
  ],
  "edges": [
    /* Original branch: code -> architecture mermaid */
    ["1", 0, "2"],
